mapper.select:
SELECT cr.room_id, cr.room_type, CASE cr.room_type WHEN 'industry' THEN i.name WHEN 'region' THEN r.name WHEN 'loan' THEN l.product_name WHEN 'policy' THEN p.policy_name ELSE NULL END AS name, (SELECT content FROM chat_messages WHERE room_id = cr.room_id ORDER BY created_at DESC LIMIT 1 ) AS lastMessage, (SELECT created_at FROM chat_messages WHERE room_id = cr.room_id ORDER BY created_at DESC LIMIT 1 ) AS lastMessageDate, uc.last_left_at, (SELECT COUNT(*) FROM chat_messages cm WHERE cm.room_id = uc.room_id AND cm.created_at > uc.last_left_at ) AS unreadCount FROM user_chat_rooms uc LEFT JOIN chat_rooms cr ON uc.room_id = cr.room_id LEFT JOIN industry i ON cr.industry_id = i.industry_id LEFT JOIN regions r ON cr.region_id = r.region_id LEFT JOIN loans l ON cr.loan_id = l.loan_id LEFT JOIN policies p ON cr.policy_id = p.policy_id
uc.user_id = #{userId}
AND cr.room_type = #{type}

SELECT cm.message_id, u.profile_image_key, u.nickname, cm.content, cm.created_at, ca.file_key, ca.file_name, ca.file_extension, ca.file_size FROM chat_messages cm LEFT JOIN users u ON cm.user_id = u.user_id LEFT JOIN chat_attachments ca ON cm.message_id = ca.message_id
cm.room_id = #{roomId}
AND cm.created_at > #{requestDto.since}
ORDER BY cm.created_at ASC
LIMIT #{requestDto.size} OFFSET #{requestDto.offset}
